// The way panel. Everything coming from OSM is inserted as text (never as HTML); the SVG
// graphics are generated by the library, which escapes all tag values.

import {
  interpretLanes,
  OsmNotFoundError,
  OsmRateLimitedError,
  OsmTimeoutError,
  renderDestinationSignElement,
  renderLanesElement,
  renderCompassElement,
  wayBearing,
  wikiUrlForKey,
  type Locale,
  type OsmWay,
} from '../src/index'

type Child = Node | string | null | undefined | false

function h<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  ...children: Child[]
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag)
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v)
  for (const c of children) {
    if (c === null || c === undefined || c === false) continue
    node.append(typeof c === 'string' ? document.createTextNode(c) : c)
  }
  return node
}

const ext = (href: string, label: string) => h('a', { href, target: '_blank', rel: 'noopener noreferrer' }, label)

const locale: Locale = navigator.language?.toLowerCase().startsWith('de') ? 'de' : 'en'

export interface PanelCallbacks {
  onClose(): void
  onRetry(): void
  /** A way was picked from the list of streets at a clicked point. */
  onPick(id: string): void
  /** A list entry is hovered or focused (id), or no longer (null). */
  onPreview(id: string | null): void
}

/** The streets found at a clicked point of a merged map feature, offered as a list. */
export interface WayChoices {
  /** Nearest first. */
  streets: { way: OsmWay; distanceM: number }[]
  /** The way ID the tile feature carries (the first merged way); listed if not found nearby. */
  hintWayId?: string
}

export class Panel {
  constructor(
    private root: HTMLElement,
    private cb: PanelCallbacks,
  ) {
    root.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') cb.onClose()
    })
  }

  get open() {
    return !this.root.hidden
  }

  close() {
    this.cb.onPreview(null)
    this.root.hidden = true
    this.root.replaceChildren()
  }

  /** Shown under the header of every way view until cleared (set to null). */
  choices: WayChoices | null = null
  private currentId: string | null = null

  private show(header: Node, ...children: Child[]) {
    const close = h('button', { class: 'close', type: 'button', 'aria-label': 'Close' }, '×')
    close.addEventListener('click', () => this.cb.onClose())
    this.cb.onPreview(null)
    const list = this.choices ? this.choiceList(this.choices) : null
    this.root.replaceChildren(close, header, ...[list, ...children].filter((c): c is Node | string => !!c))
    this.root.hidden = false
  }

  searching() {
    this.currentId = null
    this.show(this.plainHeader('Streets at this point'), h('p', { class: 'status' }, 'Looking up the OSM ways at this point…'), this.footer())
  }

  noStreets() {
    this.currentId = null
    this.show(
      this.plainHeader('Streets at this point'),
      h('p', { class: 'status' }, 'No street found at this point in the OSM data.'),
      this.footer(),
    )
  }

  searchError(err: unknown) {
    this.currentId = null
    const busy = err instanceof OsmRateLimitedError || err instanceof OsmTimeoutError
    const msg = busy
      ? 'The OSM API is busy right now. Click the road again in a moment.'
      : `Could not look up the ways at this point${err instanceof Error ? `: ${err.message}` : '.'} Click the road again to retry.`
    this.show(this.plainHeader('Streets at this point'), h('p', { class: 'status error' }, msg), this.footer())
  }

  private choiceList(c: WayChoices) {
    const item = (id: string, name: string, meta: string) => {
      const current = id === this.currentId
      const btn = h('button', { type: 'button', ...(current ? { 'aria-current': 'true' } : {}) }, h('span', { class: 'name' }, name), h('span', { class: 'meta' }, meta))
      btn.addEventListener('click', () => {
        if (!current) this.cb.onPick(id)
      })
      btn.addEventListener('mouseenter', () => this.cb.onPreview(id))
      btn.addEventListener('focus', () => this.cb.onPreview(id))
      btn.addEventListener('mouseleave', () => this.cb.onPreview(null))
      btn.addEventListener('blur', () => this.cb.onPreview(null))
      return h('li', {}, btn)
    }
    const items = c.streets.map(({ way, distanceM }) => {
      const t = way.tags
      const name = t['name'] || t['ref'] || `Way ${way.id}`
      const meta = [t['ref'] && t['name'] ? t['ref'] : '', t['highway'] ?? '', `way/${way.id}`, distanceM < 1 ? '< 1 m' : `${Math.round(distanceM)} m`]
      return item(way.id, name, meta.filter(Boolean).join(' · '))
    })
    if (c.hintWayId && !c.streets.some((s) => s.way.id === c.hintWayId)) {
      items.push(item(c.hintWayId, `Way ${c.hintWayId}`, 'first way of the merged map segment · loads on click'))
    }
    return h(
      'details',
      { class: 'choices', open: '' },
      h('summary', {}, `Streets at this point (${items.length})`),
      h('p', { class: 'hint' }, 'This map segment was merged from several OSM ways. The nearest street is shown; pick another one if it is not the right segment.'),
      h('ol', {}, ...items),
    )
  }

  private plainHeader(title: string) {
    return h('header', {}, h('h2', {}, title))
  }

  loading(id: string) {
    this.currentId = id
    this.show(this.header(`Way ${id}`, id), h('p', { class: 'status' }, 'Loading way…'), this.footer())
  }

  error(id: string, err: unknown) {
    this.currentId = id
    let msg = 'Could not load this way.'
    let retry = false
    if (err instanceof OsmNotFoundError) msg = `Way ${id} does not exist (or was deleted).`
    else if (err instanceof OsmRateLimitedError) {
      msg = 'The OSM data servers are busy right now. Please try again in a moment.'
      retry = true
    } else if (err instanceof OsmTimeoutError) {
      msg = 'The OSM data servers did not answer in time (they may be busy). Please try again in a moment.'
      retry = true
    } else if (err instanceof Error) {
      msg = `Could not load this way: ${err.message}`
      retry = true
    }
    const btn = retry ? h('button', { type: 'button', class: 'retry' }, 'Retry') : null
    btn?.addEventListener('click', () => this.cb.onRetry())
    this.show(this.header(`Way ${id}`, id), h('p', { class: 'status error' }, msg), btn, this.footer())
  }

  way(way: OsmWay) {
    this.currentId = way.id
    const t = way.tags
    const road = interpretLanes(t)
    const title = t['name'] || t['ref'] || `Way ${way.id}`
    const subtitle = [t['ref'] && t['name'] ? t['ref'] : '', t['highway'] ? `highway=${t['highway']}` : ''].filter(Boolean).join(' · ')

    const dest = renderDestinationSignElement(road, { locale })
    const lanes = renderLanesElement(road, { locale })
    // The lane graphic is drawn in way direction ("up"); the compass says where that points.
    const compass = renderCompassElement(wayBearing(way.geometry), { locale })

    const graphics = h(
      'div',
      { class: 'graphics' },
      dest ? h('figure', {}, dest, h('figcaption', {}, 'Destination sign (destination:lanes)')) : null,
      lanes
        ? h(
            'figure',
            {},
            h('div', { class: 'lanes-row' }, lanes, compass),
            h('figcaption', {}, compass ? 'Lanes in way direction (compass and map arrows)' : 'Lanes in way direction'),
          )
        : null,
    )

    const warnings = road.warnings.length
      ? h(
          'details',
          { class: 'warnings', ...(road.warnings.some((w) => w.code !== 'not-interpreted') ? { open: '' } : {}) },
          h('summary', {}, `Notes (${road.warnings.length})`),
          h('ul', {}, ...road.warnings.map((w) => h('li', {}, w.message))),
        )
      : null

    const rows = Object.keys(t)
      .sort()
      .map((k) => {
        const url = wikiUrlForKey(k)
        return h('tr', {}, h('th', {}, url ? ext(url, k) : k), h('td', {}, t[k]!))
      })
    const tags = h('details', { class: 'tags', open: '' }, h('summary', {}, `Tags (${rows.length})`), h('table', {}, h('tbody', {}, ...rows)))

    this.show(
      this.header(title, way.id, subtitle),
      lanes ? graphics : h('p', { class: 'status' }, 'This way has no lane tags. ', ext('https://wiki.openstreetmap.org/wiki/Lanes', 'How to tag lanes')),
      warnings,
      tags,
      this.footer(way),
    )
  }

  private header(title: string, id: string, subtitle?: string) {
    return h(
      'header',
      {},
      h('h2', {}, title),
      h('p', { class: 'sub' }, subtitle ? `${subtitle} · ` : '', ext(`https://www.openstreetmap.org/way/${id}`, `way/${id}`)),
    )
  }

  private footer(way?: OsmWay) {
    const via =
      way?.source === 'overpass'
        ? [
            ext('https://overpass-api.de/', 'Overpass API'),
            ' (',
            ext('https://www.fossgis.de/arbeitsgruppen/osm-server/nutzungsbedingungen/', 'FOSSGIS'),
            ')',
            way.dataTimestamp ? `, data as of ${fmtTime(way.dataTimestamp)}` : '',
          ]
        : way?.source === 'osm-api'
          ? [
              ext('https://wiki.openstreetmap.org/wiki/API_v0.6', 'OSM API'),
              way.timestamp ? `, last edited ${fmtTime(way.timestamp)}${way.version ? ` (version ${way.version})` : ''}` : '',
            ]
          : null
    return h(
      'footer',
      {},
      h('p', {}, ext('https://www.openstreetmap.org/fixthemap', 'Report a map issue')),
      h(
        'p',
        { class: 'credit' },
        'Way data: ',
        ext('https://www.openstreetmap.org/copyright', '© OpenStreetMap contributors'),
        ' (ODbL)',
        ...(via ? [', via ', ...via] : []),
        '.',
      ),
    )
  }
}

const fmtTime = (iso: string) => iso.replace('T', ' ').replace('Z', ' UTC')
